{
  "title": "CSCI-421: Principles of Database System Implementation",
  "learningObjectives": [
    "Define the core components of a relational model, including tables, keys, and constraints, and explain how they enforce data integrity.",
    "Explain how indexing and hashing structures provide efficient access paths for query processing and optimize database performance.",
    "Apply transaction management and concurrency control principles to ensure atomicity, consistency, and isolation in database operations."
  ],
  "beats": [
    {
      "title": "Foundations of the Relational Model",
      "claim": "Relational systems organize data with tables, rows, columns, and declared types.",
      "example": "A 'Students' table contains rows for each student, with columns for ID, name, and major, each assigned a specific data type like INTEGER or VARCHAR.",
      "visualDirection": "Display a simple table schema diagram with labeled columns and a sample row, highlighting the declarative nature of column types.",
      "sourceIds": ["postgresql-documentation"]
    },
    {
      "title": "Keys and Referential Integrity",
      "claim": "Primary keys identify rows, while foreign keys express references between tables.",
      "example": "A 'Courses' table uses a primary key 'CourseID' to uniquely identify each course, and a foreign key 'DepartmentID' links it to the 'Departments' table.",
      "visualDirection": "Show two connected tables with arrows indicating the primary key to foreign key relationship, emphasizing unique identification and referential links.",
      "sourceIds": ["postgresql-documentation"]
    },
    {
      "title": "Constraints and Data Rules",
      "claim": "Constraints reject states that violate declared data rules.",
      "example": "A NOT NULL constraint on a 'StudentID' column prevents empty entries, while a CHECK constraint ensures 'Age' values remain between 18 and 100.",
      "visualDirection": "Illustrate a database row with a red 'X' over a cell that violates a CHECK constraint, alongside a green checkmark for a valid entry.",
      "sourceIds": ["postgresql-documentation"]
    },
    {
      "title": "Query Operations and Schema Design",
      "claim": "Queries select, join, aggregate, insert, update, and delete data, while schema design separates entities and relationships.",
      "example": "A JOIN operation merges 'Enrollments' and 'Courses' tables to show which students are taking which classes, demonstrating how schema design supports relational queries.",
      "visualDirection": "Render a before-and-after query result showing a single table versus a joined result set, highlighting how schema separation enables complex data retrieval.",
      "sourceIds": ["postgresql-documentation"]
    },
    {
      "title": "Indexing for Efficient Lookup",
      "claim": "Indexes provide additional access paths for selected queries.",
      "example": "An index on the 'DepartmentID' column allows the database to quickly locate all courses in a specific department without scanning every row.",
      "visualDirection": "Show a B-tree index structure with sorted leaf nodes, pointing to table row locations, demonstrating how indexes accelerate data retrieval.",
      "sourceIds": ["postgresql-documentation"]
    },
    {
      "title": "Hashing for Fast Retrieval",
      "claim": "Hashing structures map keys to fixed memory locations for constant-time lookups.",
      "example": "A hash table stores 'StudentID' keys, where each ID hashes to a specific bucket, enabling rapid verification of student records during login checks.",
      "visualDirection": "Display a hash table with multiple buckets, showing how different StudentIDs map to the same or different buckets via hash functions.",
      "sourceIds": ["rit-csci-421"]
    },
    {
      "title": "Transaction Management and Atomicity",
      "claim": "Transactions group operations into an atomic unit of work.",
      "example": "A transaction transfers funds between two accounts, ensuring both the debit and credit succeed together or fail together to maintain balance consistency.",
      "visualDirection": "Show a transaction flow diagram with a commit or rollback switch, illustrating how grouped operations maintain data integrity.",
      "sourceIds": ["rit-csci-421"]
    },
    {
      "title": "Concurrency Control and Isolation",
      "claim": "Isolation controls how concurrent transactions observe one another.",
      "example": "Read committed isolation allows multiple transactions to read data simultaneously but prevents one transaction from seeing uncommitted changes from another.",
      "visualDirection": "Illustrate two concurrent transaction windows with visibility indicators, showing how isolation levels filter uncommitted data from other processes.",
      "sourceIds": ["rit-csci-421"]
    },
    {
      "title": "Query Processing and Optimization",
      "claim": "Query planning and physical structures influence performance without changing logical query meaning.",
      "example": "The optimizer chooses a hash join over a nested loop join for large tables, leveraging physical indexes to reduce execution time while preserving the same result set.",
      "visualDirection": "Compare two execution plans side-by-side, highlighting how physical structure choices affect cost and resource usage without altering logical output.",
      "sourceIds": ["rit-csci-421"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "Database system implementation requires evaluating physical organization, indexing, transaction safety, and concurrency isolation to ensure reliable performance.",
      "example": "A developer reviews a schema for missing primary keys, adds a hash index on a frequently queried column, wraps critical updates in a transaction, and sets isolation to serializable for financial records.",
      "visualDirection": "Present a checklist graphic with four checkboxes: Physical Organization, Indexing Strategy, Transaction Safety, Concurrency Isolation, each linked to corresponding implementation steps.",
      "sourceIds": ["rit-csci-421"]
    }
  ]
}
